WITH a AS (SELECT strftime('%Y-%m-%dT%H:%M:%SZ',MAX(created_at),'-1 month') cut FROM AgentTurn), pj AS (SELECT t.turn_id,t.session_id,t.template_version_id,t.created_at,u.input_tokens,u.output_tokens,u.cached_tokens,ROUND((u.input_tokens-u.cached_tokens)/1000.0*mp.input_rate+u.cached_tokens/1000.0*mp.cached_rate+u.output_tokens/1000.0*mp.output_rate,8) cost_usd FROM AgentTurn t JOIN TurnUsage u ON u.turn_id=t.turn_id JOIN ModelPrice mp ON mp.model_id=t.model_id AND t.created_at>=mp.valid_from AND (mp.valid_to IS NULL OR t.created_at<mp.valid_to) WHERE t.created_at>=(SELECT cut FROM a)) SELECT session_id,template_version_id,COUNT(*) turns,SUM(input_tokens) input_tokens,SUM(output_tokens) output_tokens,ROUND(SUM(cost_usd),6) session_cost_usd FROM pj GROUP BY session_id,template_version_id HAVING SUM(cost_usd)>0.0008 ORDER BY session_cost_usd DESC LIMIT 15;
